-- Phase 27: Government scheme catalog for informal and migrant workers.
-- Content is informational only: Pehchaan never submits applications on a
-- worker's behalf. Seed text is illustrative; NGO Admins must verify every
-- detail and official link against the latest official source before relying
-- on it. English lives in the base columns; hi/bn/ta/te overrides live in the
-- languages JSONB and are served to the app for the existing translation
-- system.
INSERT INTO welfare_schemes
  (id, slug, name, description, eligibility, registration_instructions, official_url, languages, states, worker_categories, min_age, max_age)
VALUES
  ('00000000-0000-0000-0000-000000000021', 'e-shram', 'e-Shram registration', 'A national worker database and Universal Account Number that can help workers access welfare services.', 'Informal workers with an Aadhaar-linked mobile number, subject to current government rules.', 'Register through the official e-Shram portal or ask a Common Service Centre for help.', 'https://eshram.gov.in/', '{"hi":{"name":"e-श्रम पंजीकरण","description":"एक राष्ट्रीय श्रमिक डेटाबेस और यूनिवर्सल अकाउंट नंबर, जिससे श्रमिक सरकारी सुविधाएं पाने में मदद मिल सकती है।","eligibility":"आधार से जुड़े मोबाइल नंबर वाले असंगठित श्रमिक, सरकारी नियमों के अनुसार।","registrationInstructions":"आधिकारिक e-श्रम पोर्टल से पंजीकरण करें या नज़दीकी कॉमन सर्विस सेंटर से मदद लें।"},"bn":{"name":"ই-শ্রম নিবন্ধন","description":"একটি জাতীয় শ্রমিক ডেটাবেস ও ইউনিভার্সাল অ্যাকাউন্ট নম্বর, যা শ্রমিকদের সরকারি সুবিধা পেতে সাহায্য করতে পারে।","eligibility":"আধার-যুক্ত মোবাইল নম্বরযুক্ত অসংগঠিত শ্রমিক, সরকারি নিয়ম অনুযায়ী।","registrationInstructions":"অফিসিয়াল ই-শ্রম পোর্টালে নিবন্ধন করুন বা নিকটবর্তী কমন সার্ভিস সেন্টারে সাহায্য নিন।"},"ta":{"name":"இ-ஷ்ரம் பதிவு","description":"தேசிய தொழிலாளர் தரவுத்தளமும் யுனிவர்சல் கணக்கு எண்ணும்; தொழிலாளர்கள் அரசு நலச் சேவைகளை அணுக உதவும்.","eligibility":"ஆதாருடன் இணைந்த மொபைல் எண் உள்ள சமூக அமைப்பற்ற தொழிலாளர்கள்; அரசு விதிகளுக்கு உட்பட்டவர்கள்.","registrationInstructions":"அதிகாரப்பூர்வ இ-ஷ்ரம் தளத்தில் பதிவு செய்யுங்கள் அல்லது அருகிலுள்ள காமன் சர்வீஸ் சென்டரில் உதவி பெறுங்கள்।"},"te":{"name":"ఇ-శ్రమ్ నమోదు","description":"జాతీయ కార్మిక డేటాబేస్ మరియు యూనివర్సల్ ఖాతా నంబర్; కార్మికులు ప్రభుత్వ సంక్షేమ సేవలు పొందడానికి ఉపయోగపడుతుంది.","eligibility":"ఆధార్‌కు అనుసంధానించిన మొబైల్ నంబర్ ఉన్న అసంస్థీకృత కార్మికులు; ప్రభుత్వ నియమాలకు లోబడి.","registrationInstructions":"అధికారిక ఇ-శ్రమ్ పోర్టల్‌లో నమోదు చేయండి లేదా సమీప కామన్ సర్వీస్ సెంటర్‌లో సహాయం తీసుకోండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], 16, 59),
  ('00000000-0000-0000-0000-000000000022', 'pm-sym', 'PM-SYM pension', 'A voluntary contributory pension scheme for eligible unorganised workers.', 'Generally for eligible unorganised workers aged 18-40 with income and contribution conditions.', 'Check eligibility and enrol through an official CSC or the PM-SYM portal.', 'https://labour.gov.in/pm-sym', '{"hi":{"name":"पीएम-श्रम योगी मांधन (PM-SYM) पेंशन","description":"असंगठित श्रमिकों के लिए स्वैच्छिक योगदान आधारित पेंशन योजना।","eligibility":"आमतौर पर 18–40 वर्ष के पात्र असंगठित श्रमिक; आय और योगदान की शर्तें लागू।","registrationInstructions":"पात्रता जांचें और आधिकारिक CSC या PM-SYM पोर्टल से नामांकन कराएं।"},"bn":{"name":"পিএম-শ্রম যোগী মান্ধন (PM-SYM) পেনশন","description":"অসংগঠিত শ্রমিকদের জন্য স্বেচ্ছাভিত্তিক অবদানভিত্তিক পেনশন স্কিম।","eligibility":"সাধারণত 18–40 বছর বয়সী যোগ্য অসংগঠিত শ্রমিক; আয় ও অবদানের শর্ত প্রযোজ্য।","registrationInstructions":"যোগ্যতা যাচাই করে অফিসিয়াল CSC বা PM-SYM পোর্টালের মাধ্যমে ভর্তি হন।"},"ta":{"name":"பிஎம்-ஷ்ரம் யோகி மாந்தன் (PM-SYM) ஓய்வூதியம்","description":"சமூக அமைப்பற்ற தொழிலாளர்களுக்கான தன்னார்வ பங்களிப்பு ஓய்வூதியத் திட்டம்.","eligibility":"பொதுவாக 18–40 வயதுடைய தகுதியான தொழிலாளர்கள்; வருமான மற்றும் பங்களிப்பு நிபந்தனைகள் உண்டு.","registrationInstructions":"தகுதியைச் சரிபார்த்து, அதிகாரப்பூர்வ CSC அல்லது PM-SYM தளத்தில் பதிவு செய்யுங்கள்।"},"te":{"name":"పిఎం-శ్రమ యోగి మాంధన్ (PM-SYM) పెన్షన్","description":"అసంస్థీకృత కార్మికుల కోసం స్వచ్ఛంద సహకార ఆధారిత పెన్షన్ పథకం.","eligibility":"సాధారణంగా 18–40 ఏళ్ల అర్హులైన అసంస్థీకృత కార్మికులు; ఆదాయం, చందా నిబంధనలు వర్తిస్తాయి.","registrationInstructions":"అర్హత తనిఖీ చేసి, అధికారిక CSC లేదా PM-SYM పోర్టల్ ద్వారా నమోదు చేయండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], 18, 40),
  ('00000000-0000-0000-0000-000000000023', 'ayushman-bharat', 'Ayushman Bharat', 'Health-cover support for eligible families under the applicable government list.', 'Eligibility depends on the government beneficiary database and current scheme rules.', 'Check eligibility at an official Ayushman Bharat help desk or portal.', 'https://pmjay.gov.in/', '{"hi":{"name":"आयुष्मान भारत (PM-JAY)","description":"पात्र परिवारों के लिए सरकारी सूची के अनुसार स्वास्थ्य बीमा सहायता।","eligibility":"पात्रता सरकारी लाभार्थी डेटाबेस और नवीनतम नियमों पर निर्भर करती है।","registrationInstructions":"आधिकारिक आयुष्मान भारत हेल्प डेस्क या पोर्टल पर पात्रता जांचें।"},"bn":{"name":"আয়ুষ্মান ভারত (PM-JAY)","description":"যোগ্য পরিবারগুলির জন্য সরকারি তালিকা অনুযায়ী স্বাস্থ্য বিমা সহায়তা।","eligibility":"যোগ্যতা নির্ভর করে সরকারি উপভোক্তা ডেটাবেস ও বর্তমান নিয়মের উপর।","registrationInstructions":"অফিসিয়াল আয়ুষ্মান ভারত হেল্প ডেস্ক বা পোর্টালে যোগ্যতা যাচাই করুন।"},"ta":{"name":"ஆயுஷ்மான் பாரத் (PM-JAY)","description":"தகுதியான குடும்பங்களுக்கு அரசு பட்டியலின்படி சுகாதாரக் காப்பீட்டு உதவி.","eligibility":"தகுதி அரசு பயனர் தரவுத்தளம் மற்றும் தற்போதைய விதிகளைப் பொறுத்தது.","registrationInstructions":"அதிகாரப்பூர்வ ஆயுஷ்மான் பாரத் உதவி மையம் அல்லது தளத்தில் தகுதியைச் சரிபார்க்கவும்।"},"te":{"name":"ఆయుష్మాన్ భారత్ (PM-JAY)","description":"అర్హమైన కుటుంబాలకు ప్రభుత్వ జాబితా ప్రకారం ఆరోగ్య బీమా సహాయం.","eligibility":"అర్హత ప్రభుత్వ లబ్ధిదారుల డేటాబేస్ మరియు ప్రస్తుత నియమాలపై ఆధారపడి ఉంటుంది.","registrationInstructions":"అధికారిక ఆయుష్మాన్ భారత్ సహాయ కేంద్రం లేదా పోర్టల్‌లో అర్హత తనిఖీ చేయండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], NULL, NULL),
  ('00000000-0000-0000-0000-000000000024', 'esic', 'ESIC', 'Health and social-security benefits for workers covered through an eligible employer.', 'Usually applies where the employer and wage conditions bring the worker under ESIC.', 'Ask the employer or nearest ESIC office to confirm coverage and registration.', 'https://www.esic.gov.in/', '{"hi":{"name":"ईएसआईसी (ESIC)","description":"योग्य नियोक्ता के माध्यम से कवर होने वाले श्रमिकों के लिए स्वास्थ्य और सामाजिक सुरक्षा लाभ।","eligibility":"आमतौर पर तब लागू जब नियोक्ता और वेतन की शर्तें श्रमिक को ESIC के अंतर्गत लाती हों।","registrationInstructions":"नियोक्ता या नज़दीकी ESIC कार्यालय से कवरेज और पंजीकरण की पुष्टि कराएं।"},"bn":{"name":"ইএসআইসি (ESIC)","description":"যোগ্য নিয়োগকর্তার মাধ্যমে আচ্ছাদিত শ্রমিকদের জন্য স্বাস্থ্য ও সামাজিক নিরাপত্তা সুবিধা।","eligibility":"সাধারণত তখনই প্রযোজ্য যখন নিয়োগকর্তা ও মজুরির শর্ত শ্রমিককে ESIC-এর আওতায় আনে।","registrationInstructions":"নিয়োগকর্তা বা নিকটবর্তী ESIC অফিসে কভারেজ ও নিবন্ধন নিশ্চিত করুন।"},"ta":{"name":"ஈஎஸ்ஐசி (ESIC)","description":"தகுதியான முதலாளி வழியாக உள்ளடக்கப்படும் தொழிலாளர்களுக்கான சுகாதார மற்றும் சமூக பாதுகாப்பு நலன்கள்.","eligibility":"பொதுவாக முதலாளி மற்றும் கூலி நிபந்தனைகள் தொழிலாளியை ESIC-இன் கீழ் கொண்டுவரும்போது பொருந்தும்.","registrationInstructions":"முதலாளி அல்லது அருகிலுள்ள ESIC அலுவலகத்தில் உறைவு மற்றும் பதிவை உறுதிப்படுத்துங்கள்।"},"te":{"name":"ఈఎస్‌ఐసి (ESIC)","description":"అర్హమైన యజమాని ద్వారా కవర్ అయ్యే కార్మికులకు ఆరోగ్య మరియు సాంఘిక భద్రతా సౌకర్యాలు.","eligibility":"సాధారణంగా యజమాని, వేతన నిబంధనలు కార్మికుడిని ESIC పరిధిలోకి తెచ్చినప్పుడు వర్తిస్తుంది.","registrationInstructions":"యజమాని లేదా సమీప ESIC కార్యాలయంలో కవరేజ్ మరియు నమోదును ఖరారు చేయండి।"}}', ARRAY['All India'], ARRAY['factory', 'construction', 'formal_employment'], NULL, NULL),
  ('00000000-0000-0000-0000-000000000025', 'pm-svanidhi', 'PM SVANidhi (street vendors)', 'Working-capital micro-loan and support for street vendors, with digital payment incentives.', 'Street vendors with a certificate of vending or vendor identification, per current rules.', 'Apply through the official PM SVANidhi portal or a lending bank/CSC with vendor documents.', 'https://pmsvanidhi.mopa.gov.in/', '{"hi":{"name":"पीएम स्वनिधि (थेला/रेहड़ी विक्रेता)","description":"थेला/रेहड़ी विक्रेताओं के लिए कामकाजी पूंजी का सूक्ष्म ऋण और डिजिटल भुगतान प्रोत्साहन।","eligibility":"विक्रेता प्रमाणपत्र या विक्रेता पहचान वाले थेला विक्रेता, नवीनतम नियमों के अनुसार।","registrationInstructions":"आधिकारिक PM SVANidhi पोर्टल या विक्रेता दस्तावेज़ों के साथ बैंक/CSC से आवेदन करें।"},"bn":{"name":"পিএম স্বনিধি (স্ট্রিট ভেন্ডার)","description":"স্ট্রিট ভেন্ডারদের জন্য কার্যকরী মূলধনের ক্ষুদ্র ঋণ ও ডিজিটাল পেমেন্ট প্রণোদনা।","eligibility":"ভেন্ডিং সার্টিফিকেট বা ভেন্ডর পরিচয়পত্রযুক্ত স্ট্রিট ভেন্ডার, বর্তমান নিয়ম অনুযায়ী।","registrationInstructions":"অফিসিয়াল PM SVANidhi পোর্টাল বা ভেন্ডর ডকুমেন্টসহ ব্যাংক/CSC-এর মাধ্যমে আবেদন করুন।"},"ta":{"name":"பிஎம் ஸ்வநிதி (தெருவோர வணிகர்கள்)","description":"தெருவோர வணிகர்களுக்கான முதலீட்டு நுண் கடன் மற்றும் டிஜிட்டல் பணப் பரிவர்த்தனை ஊக்கத்தொகை.","eligibility":"விற்பனைச் சான்றிதழ் அல்லது வணிகர் அடையாள ஆவணம் உள்ள தெருவோர வணிகர்கள், தற்போதைய விதிகளின்படி.","registrationInstructions":"அதிகாரப்பூர்வ PM SVANidhi தளம் அல்லது வணிகர் ஆவணங்களுடன் வங்கி/CSC வழியாக விண்ணப்பிக்கவும்।"},"te":{"name":"పిఎం స్వనిధి (వీధి వ్యాపారులు)","description":"వీధి వ్యాపారుల కోసం పని మూలధన సూక్ష్మ రుణం మరియు డిజిటల్ చెల్లింపుల ప్రోత్సాహకం.","eligibility":"విక్రయ ధృవీకరణ పత్రం లేదా వ్యాపారి గుర్తింపు ఉన్న వీధి వ్యాపారులు, ప్రస్తుత నియమాల ప్రకారం.","registrationInstructions":"అధికారిక PM SVANidhi పోర్టల్ లేదా వ్యాపారి పత్రాలతో బ్యాంక్/CSC ద్వారా దరఖాస్తు చేయండి।"}}', ARRAY['All India'], ARRAY['street_vendor'], 18, NULL),
  ('00000000-0000-0000-0000-000000000026', 'bocw-welfare-board', 'Construction workers welfare board (BOCW)', 'State construction workers welfare boards offer benefits like education help, maternity support, tool kits, and accident assistance for registered construction workers.', 'Construction workers who register with their state''s welfare board, usually within an age range and with work-day proof.', 'Register at your state''s BOCW welfare board office or labour department; a Common Service Centre can help.', NULL, '{"hi":{"name":"निर्माण श्रमिक कल्याण बोर्ड (BOCW)","description":"राज्य निर्माण श्रमिक कल्याण बोर्ड पंजीकृत निर्माण श्रमिकों को शिक्षा सहायता, मातृत्व सहायता, औज़ार किट और दुर्घटना सहायता जैसे लाभ देते हैं।","eligibility":"अपने राज्य के कल्याण बोर्ड में पंजीकरण कराने वाले निर्माण श्रमिक; आमतौर पर आयु सीमा और कार्य-दिवस प्रमाण ज़रूरी है।","registrationInstructions":"अपने राज्य के BOCW कल्याण बोर्ड कार्यालय या श्रम विभाग में पंजीकरण करें; कॉमन सर्विस सेंटर भी मदद कर सकता है।"},"bn":{"name":"নির্মাণ শ্রমিক কল্যাণ বোর্ড (BOCW)","description":"রাজ্য নির্মাণ শ্রমিক কল্যাণ বোর্ড নিবন্ধিত নির্মাণ শ্রমিকদের শিক্ষা সহায়তা, মাতৃত্ব সহায়তা, সরঞ্জাম কিট ও দুর্ঘটনা সহায়তা দেয়।","eligibility":"নিজের রাজ্যের কল্যাণ বোর্ডে নিবন্ধিত নির্মাণ শ্রমিক; সাধারণত বয়সসীমা ও কাজের দিনের প্রমাণ লাগে।","registrationInstructions":"নিজের রাজ্যের BOCW কল্যাণ বোর্ড অফিস বা শ্রম দফতরে নিবন্ধন করুন; কমন সার্ভিস সেন্টারও সাহায্য করতে পারে।"},"ta":{"name":"கட்டுமானத் தொழிலாளர் நல வாரியம் (BOCW)","description":"மாநில கட்டுமானத் தொழிலாளர் நல வாரியங்கள், பதிவு செய்த கட்டுமானத் தொழிலாளர்களுக்குக் கல்வி உதவி, தாய்மை உதவி, கருவித் தொகுப்பு, விபத்து உதவி வழங்குகின்றன.","eligibility":"தங்கள் மாநில நல வாரியத்தில் பதிவு செய்யும் கட்டுமானத் தொழிலாளர்கள்; பொதுவாக வயது வரம்பும் வேலை நாட்கள் சான்றும் தேவை.","registrationInstructions":"உங்கள் மாநில BOCW நல வாரிய அலுவலகம் அல்லது தொழிலாளர் துறையில் பதிவு செய்யுங்கள்; காமன் சர்வீஸ் சென்டரும் உதவும்।"},"te":{"name":"నిర్మాణ కార్మిక సంక్షేమ బోర్డు (BOCW)","description":"రాష్ట్ర నిర్మాణ కార్మిక సంక్షేమ బోర్డులు, నమోదైన నిర్మాణ కార్మికులకు విద్యా సహాయం, మాతృత్వ సహాయం, పనిముట్ల కిట్, ప్రమాద సహాయం అందిస్తాయి.","eligibility":"తమ రాష్ట్ర సంక్షేమ బోర్డులో నమోదు చేసుకునే నిర్మాణ కార్మికులు; సాధారణంగా వయసు పరిధి మరియు పనిదినాల ఆధారం అవసరం.","registrationInstructions":"మీ రాష్ట్ర BOCW సంక్షేమ బోర్డు కార్యాలయం లేదా కార్మిక శాఖలో నమోదు చేయండి; కామన్ సర్వీస్ సెంటర్ కూడా సహాయం చేస్తుంది।"}}', ARRAY['All India'], ARRAY['unskilled_construction', 'semi_skilled_construction', 'skilled_construction'], 18, 60),
  ('00000000-0000-0000-0000-000000000027', 'pm-awas', 'PM Awas Yojana (housing)', 'Housing support for eligible families under the applicable urban or rural housing scheme rules.', 'Eligibility depends on the government housing beneficiary list and current scheme rules.', 'Check with your local panchayat, urban local body, or the official PM Awas (urban/rural) portal.', NULL, '{"hi":{"name":"पीएम आवास योजना (आवास)","description":"लागू शहरी या ग्रामीण आवास नियमों के अनुसार पात्र परिवारों को आवास सहायता।","eligibility":"पात्रता सरकारी आवास लाभार्थी सूची और नवीनतम नियमों पर निर्भर करती है।","registrationInstructions":"अपनी पंचायत, नगर निकाय या आधिकारिक PM Awas (शहरी/ग्रामीण) पोर्टल से जांच करें।"},"bn":{"name":"পিএম আবাস যোজনা (আবাসন)","description":"প্রযোজ্য শহর বা গ্রামীণ আবাসন নিয়ম অনুযায়ী যোগ্য পরিবারের জন্য আবাসন সহায়তা।","eligibility":"যোগ্যতা নির্ভর করে সরকারি আবাসন উপভোক্তা তালিকা ও বর্তমান নিয়মের উপর।","registrationInstructions":"স্থানীয় পঞ্চায়েত, পৌরসংস্থা বা অফিসিয়াল PM Awas (শহর/গ্রাম) পোর্টালে যাচাই করুন।"},"ta":{"name":"பிஎம் ஆவாஸ் யோஜனா (வீடு)","description":"பொருந்தக்கூடிய நகர்ப்புற அல்லது ஊரக வீட்டுத் திட்ட விதிகளின்படி தகுதியான குடும்பங்களுக்கான வீட்டு உதவி.","eligibility":"தகுதி அரசு வீட்டு உதவி பயனர் பட்டியல் மற்றும் தற்போதைய விதிகளைப் பொறுத்தது.","registrationInstructions":"உங்கள் ஊராட்சி, நகராட்சி அல்லது அதிகாரப்பூர்வ PM Awas (நகர்ப்புற/ஊரக) தளத்தில் சரிபார்க்கவும்।"},"te":{"name":"పిఎం ఆవాస్ యోజన (గృహం)","description":"వర్తించే పట్టణ లేదా గ్రామీణ గృహ పథకాల నియమాల ప్రకారం అర్హమైన కుటుంబాలకు గృహ సహాయం.","eligibility":"అర్హత ప్రభుత్వ గృహ లబ్ధిదారుల జాబితా మరియు ప్రస్తుత నియమాలపై ఆధారపడి ఉంటుంది.","registrationInstructions":"మీ పంచాయతీ, పట్టణ స్థానిక సంస్థ లేదా అధికారిక PM Awas (పట్టణ/గ్రామీణ) పోర్టల్‌లో తనిఖీ చేయండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], NULL, NULL),
  ('00000000-0000-0000-0000-000000000028', 'onorc', 'One Nation One Ration Card (rations anywhere)', 'Lets eligible ration-card families collect food grains from any fair-price shop in India, which is especially useful for migrant workers.', 'Families with a ration card linked to the national portability features; rules vary by state.', 'Ask your state food supplies office to confirm portability, and use the Mera Ration app or portal.', NULL, '{"hi":{"name":"वन नेशन वन रेशन कार्ड (कहीं भी राशन)","description":"पात्र राशन कार्ड परिवारों को भारत में किसी भी उचित मूल्य की दुकान से अनाज लेने की सुविधा; प्रवासी श्रमिकों के लिए खास उपयोगी।","eligibility":"राष्ट्रीय पोर्टेबिलिटी से जुड़े राशन कार्ड वाले परिवार; नियम राज्य के अनुसार बदलते हैं।","registrationInstructions":"अपने राज्य के खाद्य आपूर्ति कार्यालय से पोर्टेबिलिटी की पुष्टि कराएं और Mera Ration ऐप/पोर्टल इस्तेमाल करें।"},"bn":{"name":"ওয়ান নেশন ওয়ান রেশন কার্ড (যেকোনো জায়গায় রেশন)","description":"যোগ্য রেশন কার্ড পরিবার ভারতের যেকোনো ন্যায্য মূল্যের দোকান থেকে খাদ্যশস্য সংগ্রহ করতে পারে; প্রবাসী শ্রমিকদের জন্য বিশেষ দরকারি।","eligibility":"জাতীয় পোর্টেবিলিটির সঙ্গে যুক্ত রেশন কার্ডধারী পরিবার; নিয়ম রাজ্যভেদে আলাদা।","registrationInstructions":"রাজ্যের খাদ্য সরবরাহ অফিসে পোর্টেবিলিটি নিশ্চিত করে Mera Ration অ্যাপ/পোর্টাল ব্যবহার করুন।"},"ta":{"name":"ஒன் நேஷன் ஒன் ரேஷன் கார்டு (எங்கும் ரேஷன்)","description":"தகுதியான ரேஷன் கார்டு குடும்பங்கள் இந்தியாவில் எந்த நியாய விலைக் கடையிலும் தானியங்களைப் பெறலாம்; குடிபெயர்ந்த தொழிலாளர்களுக்கு மிகப் பயனுள்ளது.","eligibility":"தேசிய இடமாறும் தன்மையுடன் இணைக்கப்பட்ட ரேஷன் கார்டு குடும்பங்கள்; விதிகள் மாநிலத்தைப் பொறுத்தது.","registrationInstructions":"உங்கள் மாநில உணவு வழங்கல் அலுவலகத்தில் இடமாறும் தன்மையை உறுதிசெய்து, Mera Ration செயலி/தளத்தைப் பயன்படுத்துங்கள்।"},"te":{"name":"వన్ నేషన్ వన్ రేషన్ కార్డు (ఎక్కడైనా రేషన్)","description":"అర్హమైన రేషన్ కార్డు కుటుంబాలు భారతదేశంలో ఏ న్యాయధర దుకాణంలోనైనా ధాన్యాలు పొందగలవు; వలస కార్మికులకు ముఖ్యంగా ఉపయోగకరం.","eligibility":"జాతీయ పోర్టబిలిటీకి అనుసంధానమైన రేషన్ కార్డు కుటుంబాలు; నియమాలు రాష్ట్రాన్ని బట్టి ఉంటాయి.","registrationInstructions":"మీ రాష్ట్ర ఆహార సరఫరా కార్యాలయంలో పోర్టబిలిటీని ధృవీకరించి, Mera Ration యాప్/పోర్టల్ వాడండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], NULL, NULL),
  ('00000000-0000-0000-0000-000000000029', 'old-age-pension', 'Old age pension (national/state)', 'Monthly pension support for eligible older people from poor households, run nationally and by states.', 'Generally for people aged 60+ from eligible low-income households; exact rules vary by state.', 'Apply at your block/tehsil office, panchayat, or state social welfare department.', NULL, '{"hi":{"name":"वृद्धावस्था पेंशन (राष्ट्रीय/राज्य)","description":"गरीब परिवारों के वयोवृद्ध लोगों के लिए मासिक पेंशन सहायता; राष्ट्रीय और राज्य स्तर पर चलती है।","eligibility":"आमतौर पर पात्र कम-आय परिवारों के 60+ वर्ष के लोग; सटीक नियम राज्य के अनुसार।","registrationInstructions":"अपने ब्लॉक/तहसील कार्यालय, पंचायत या राज्य समाज कल्याण विभाग में आवेदन करें।"},"bn":{"name":"বার্ধক্য ভাতা (জাতীয়/রাজ্য)","description":"দরিদ্র পরিবারের প্রবীণদের জন্য মাসিক ভাতা সহায়তা; জাতীয় ও রাজ্য স্তরে পরিচালিত।","eligibility":"সাধারণত যোগ্য নিম্ন-আয় পরিবারের 60+ বছর বয়সী ব্যক্তিরা; নিয়ম রাজ্যভেদে আলাদা।","registrationInstructions":"আপনার ব্লক/তহসিল অফিস, পঞ্চায়েত বা রাজ্য সমাজকল্যাণ দফতরে আবেদন করুন।"},"ta":{"name":"முதுமை ஓய்வூதியம் (தேசிய/மாநில)","description":"வறுமையில் வாழும் குடும்பங்களின் மூத்தோருக்கான மாத ஓய்வூதிய உதவி; தேசிய மற்றும் மாநில அளவில் நடைபெறுகிறது.","eligibility":"பொதுவாகத் தகுதியான குறைந்த வருமானக் குடும்பங்களைச் சேர்ந்த 60+ வயதினர்; விதிகள் மாநிலத்தைப் பொறுத்தது.","registrationInstructions":"உங்கள் வட்டாட்சியர் அலுவலகம், ஊராட்சி அல்லது மாநில சமூக நலத்துறையில் விண்ணப்பிக்கவும்।"},"te":{"name":"వృద్ధాప్య పెన్షన్ (జాతీయ/రాష్ట్ర)","description":"పేద కుటుంబాలలోని వృద్ధులకు నెలవారీ పెన్షన్ సహాయం; జాతీయ మరియు రాష్ట్ర స్థాయిల్లో నడుస్తుంది.","eligibility":"సాధారణంగా అర్హమైన తక్కువ ఆదాయ కుటుంబాలకు చెందిన 60+ ఏళ్ల వారు; నియమాలు రాష్ట్రాన్ని బట్టి ఉంటాయి.","registrationInstructions":"మీ బ్లాక్/తహశీల్ కార్యాలయం, పంచాయతీ లేదా రాష్ట్ర సంక్షేమ శాఖలో దరఖాస్తు చేయండి।"}}', ARRAY['All India'], ARRAY[]::TEXT[], 60, NULL),
  ('00000000-0000-0000-0000-000000000030', 'domestic-workers-board', 'Domestic workers welfare board (select states)', 'Some states run welfare boards for domestic workers with benefits like health cover, education help, and accident support.', 'Domestic workers registered with their state''s domestic workers welfare board, where it exists.', 'Ask your state''s labour department whether a domestic workers welfare board exists and how to register.', NULL, '{"hi":{"name":"घरेलू कामगार कल्याण बोर्ड (चुनिंदा राज्य)","description":"कुछ राज्य घरेलू कामगारों के लिए कल्याण बोर्ड चलाते हैं, जिनमें स्वास्थ्य सुरक्षा, शिक्षा सहायता और दुर्घटना सहायता जैसे लाभ होते हैं।","eligibility":"अपने राज्य के घरेलू कामगार कल्याण बोर्ड में पंजीकृत घरेलू कामगार, जहां बोर्ड मौजूद है।","registrationInstructions":"अपने राज्य के श्रम विभाग से पूछें कि घरेलू कामगार कल्याण बोर्ड है या नहीं और कैसे पंजीकरण करें।"},"bn":{"name":"গৃহকর্মী কল্যাণ বোর্ড (নির্বাচিত রাজ্য)","description":"কিছু রাজ্যে গৃহকর্মীদের জন্য কল্যাণ বোর্ড আছে; স্বাস্থ্য কভার, শিক্ষা সহায়তা ও দুর্ঘটনা সহায়তা দেয়।","eligibility":"নিজের রাজ্যের গৃহকর্মী কল্যাণ বোর্ডে নিবন্ধিত গৃহকর্মী, যেখানে বোর্ড আছে।","registrationInstructions":"রাজ্যের শ্রম দফতরে জিজ্ঞাসা করুন গৃহকর্মী কল্যাণ বোর্ড আছে কি না এবং কীভাবে নিবন্ধন করবেন।"},"ta":{"name":"வீட்டுப் பணியாளர் நல வாரியம் (தேர்ந்தெடுத்த மாநிலங்கள்)","description":"சில மாநிலங்கள் வீட்டுப் பணியாளர்களுக்கு நல வாரியங்களை நடத்துகின்றன; சுகாதாரக் காப்பீடு, கல்வி உதவி, விபத்து உதவி வழங்குகின்றன.","eligibility":"தங்கள் மாநில வீட்டுப் பணியாளர் நல வாரியத்தில் பதிவு செய்த பணியாளர்கள், வாரியம் இருந்தால்.","registrationInstructions":"உங்கள் மாநிலத் தொழிலாளர் துறையிடம் வீட்டுப் பணியாளர் நல வாரியம் உள்ளதா, எப்படிப் பதிவு செய்வது என்று கேளுங்கள்।"},"te":{"name":"గృహ కార్మికుల సంక్షేమ బోర్డు (ఎంపిక చేసిన రాష్ట్రాలు)","description":"కొన్ని రాష్ట్రాలు గృహ కార్మికుల కోసం సంక్షేమ బోర్డులు నడుస్తాయి; ఆరోగ్య కవర్, విద్యా సహాయం, ప్రమాద సహాయం అందిస్తాయి.","eligibility":"తమ రాష్ట్ర గృహ కార్మికుల సంక్షేమ బోర్డులో నమోదైన కార్మికులు, బోర్డు ఉన్నచోట.","registrationInstructions":"మీ రాష్ట్ర కార్మిక శాఖను సంప్రదించి గృహ కార్మికుల సంక్షేమ బోర్డు ఉందో, ఎలా నమోదు చేయాలో తెలుసుకోండి।"}}', ARRAY['All India'], ARRAY['domestic_work'], NULL, NULL)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  eligibility = EXCLUDED.eligibility,
  registration_instructions = EXCLUDED.registration_instructions,
  official_url = EXCLUDED.official_url,
